  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C02"],
      "claim": "Warfarin, the direct non-nitrated analogue of the query 4-hydroxycoumarin scaffold, has nearly complete oral bioavailability in humans, strongly supporting high F for the p-nitro derivative.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C45"],
      "claim": "Salicylate, representing the acidic aromatic system related to the 4-hydroxycoumarin enol, showed complete absolute oral bioavailability in normal subjects.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C44"],
      "claim": "Diflunisal, a salicylate-related aromatic acid, had 89.5% absolute oral bioavailability versus IV, supporting high F for acidic aromatic drugs.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Baclofen, a small polar ionizable drug, had 81.2% absolute oral bioavailability in healthy subjects, showing that polar/acidic features do not preclude F ≥20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Labetalol, despite substantial first-pass metabolism, had 29.9% absolute oral bioavailability in normal subjects, above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Terodiline had 92% mean absolute oral bioavailability in healthy volunteers, providing additional high-transfer support for high F.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Predicted high: the query is a p-nitro warfarin analogue, and warfarin itself has nearly complete oral bioavailability. Multiple high-transfer human absolute-F measurements for related acidic/aromatic drugs are well above 20%, and no strong low-bioavailability evidence transfers to the 4-hydroxycoumarin scaffold.",
  "evidence_gaps": [
    "No direct human absolute bioavailability measurement for the exact p-nitro warfarin analogue.",
    "The effect of the p-nitro substituent on first-pass metabolism, permeability, or solubility is not directly covered by the retrieved records.",
    "Some retrieved records have conflicting SMILES/drug-name annotations, adding uncertainty to structural transfer."
  ],
